<?php
require dirname(__DIR__).'/config/bootstrap.php';require dirname(__DIR__).'/src/checklists.php';
$user=auth();$db=db();$month=(string)($_GET['month']??date('Y-m'));
if(!validMonth($month)){http_response_code(400);exit('Invalid month');}
$error='';
try {
 if($_SERVER['REQUEST_METHOD']==='POST') {
  checkCsrf();$action=(string)($_POST['action']??'');
  if($action==='add_template') {
   $title=taskText((string)($_POST['title']??''));
   $q=$db->prepare('INSERT INTO checklist_templates(user_id,title,position) SELECT ?,?,COALESCE(MAX(position),0)+1 FROM checklist_templates WHERE user_id=?');$q->execute([$user,$title,$user]);
   flash('Default task added. It will appear in months created from now on.');redirect('/index.php?month='.urlencode($month).'#template');
  }
  if($action==='rename_template'||$action==='toggle_template') {
   $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);
   if(!$id)throw new InvalidArgumentException('Invalid template task');
   if($action==='rename_template') {$q=$db->prepare('UPDATE checklist_templates SET title=? WHERE id=? AND user_id=?');$q->execute([taskText((string)($_POST['title']??'')),$id,$user]);}
   else {$q=$db->prepare('UPDATE checklist_templates SET active=1-active WHERE id=? AND user_id=?');$q->execute([$id,$user]);}
   redirect('/index.php?month='.urlencode($month).'#template');
  }
  $checklist=ensureMonth($db,$user,$month);
  if($action==='add_extra') {
   $q=$db->prepare('INSERT INTO monthly_checklist_items(checklist_id,title,is_extra,position) SELECT ?,?,1,COALESCE(MAX(position),0)+1 FROM monthly_checklist_items WHERE checklist_id=?');$q->execute([$checklist,taskText((string)($_POST['title']??'')),$checklist]);
  } elseif($action==='toggle_item'||$action==='delete_extra') {
   $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);
   if(!$id || !ownedItem($db,$id,$user,$month))throw new InvalidArgumentException('Invalid item');
   if($action==='toggle_item') {$q=$db->prepare('UPDATE monthly_checklist_items SET is_done=1-is_done,completed_at=IF(is_done=1,NULL,NOW()) WHERE id=? AND checklist_id=?');$q->execute([$id,$checklist]);}
   else {$q=$db->prepare('DELETE FROM monthly_checklist_items WHERE id=? AND checklist_id=? AND is_extra=1');$q->execute([$id,$checklist]);}
  } else throw new InvalidArgumentException('Invalid action');
  redirect('/index.php?month='.urlencode($month));
 }
 $checklist=ensureMonth($db,$user,$month);
} catch(InvalidArgumentException $ex) {$error=$ex->getMessage();$checklist=ensureMonth($db,$user,$month);}
$q=$db->prepare('SELECT id,title,is_extra,is_done,completed_at FROM monthly_checklist_items WHERE checklist_id=? ORDER BY position,id');$q->execute([$checklist]);$items=$q->fetchAll();
$q=$db->prepare('SELECT id,title,active FROM checklist_templates WHERE user_id=? ORDER BY position,id');$q->execute([$user]);$templates=$q->fetchAll();
$total=count($items);$completed=count(array_filter($items,static function($x){return (int)$x['is_done']===1;}));$percent=$total?round($completed/$total*100):0;
$prev=date('Y-m',strtotime($month.'-01 -1 month'));$next=date('Y-m',strtotime($month.'-01 +1 month'));
$flash=$_SESSION['flash']??'';unset($_SESSION['flash']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e(date('F Y',strtotime($month.'-01')))?> · Monthly Checklist</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="/assets/style.css"></head><body><header class="container py-4 d-flex justify-content-between align-items-center"><a href="/index.php" class="brand text-decoration-none">☑ Monthly Checklist</a><form action="/logout.php" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button class="btn btn-sm btn-outline-secondary">Log out</button></form></header><main class="container pb-5" style="max-width:760px"><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($flash):?><div class="alert alert-success"><?=e($flash)?></div><?php endif;?><section class="card border-0 shadow-sm p-4 mb-4"><div class="d-flex justify-content-between align-items-center gap-2"><a class="btn btn-outline-secondary" href="?month=<?=e($prev)?>" aria-label="Previous month">←</a><div class="text-center"><div class="text-secondary small">YOUR MONTH</div><h1 class="h3 mb-0"><?=e(date('F Y',strtotime($month.'-01')))?></h1></div><a class="btn btn-outline-secondary" href="?month=<?=e($next)?>" aria-label="Next month">→</a></div><div class="d-flex justify-content-between mt-4 mb-2"><strong><?=$completed?> of <?=$total?> completed</strong><span class="text-secondary"><?=$percent?>%</span></div><progress class="w-100" value="<?=$completed?>" max="<?=max(1,$total)?>" aria-label="Monthly completion progress"></progress><div class="mt-3 text-center"><a href="/index.php" class="small">Jump to current month</a></div></section><section class="card border-0 shadow-sm p-4 mb-4"><h2 class="h5 mb-3">This month's tasks</h2><?php if(!$items):?><p class="text-secondary">No tasks yet. Add a default task below or a one-time task here.</p><?php endif;?><?php foreach($items as $item):?><div class="task-row d-flex align-items-center gap-2 py-2 border-bottom"><form method="post" class="flex-grow-1"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="toggle_item"><input type="hidden" name="id" value="<?=e($item['id'])?>"><button class="task-toggle d-flex align-items-center gap-3 text-start w-100 <?=((int)$item['is_done']===1?'is-done':'')?>" aria-label="Toggle <?=e($item['title'])?>"><span class="tick"><?=((int)$item['is_done']===1?'✓':'')?></span><span class="flex-grow-1"><?=e($item['title'])?></span><?php if((int)$item['is_extra']===1):?><span class="badge text-bg-light">Extra</span><?php endif;?></button></form><?php if((int)$item['is_extra']===1):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete_extra"><input type="hidden" name="id" value="<?=e($item['id'])?>"><button class="btn btn-sm btn-outline-danger" aria-label="Delete extra task">×</button></form><?php endif;?></div><?php endforeach;?><form method="post" class="d-flex gap-2 mt-4"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="add_extra"><input class="form-control" name="title" maxlength="180" placeholder="Add a task just for this month" required aria-label="Extra task title"><button class="btn btn-dark text-nowrap">Add extra</button></form></section><section id="template" class="card border-0 shadow-sm p-4"><div class="d-flex justify-content-between gap-3"><h2 class="h5">Default template</h2><span class="text-secondary small">Future months only</span></div><p class="text-secondary small">Template edits never change a month already opened. Disable a task to stop copying it into new months.</p><?php foreach($templates as $template):?><div class="py-2 border-bottom"><form method="post" class="d-flex gap-2 align-items-center"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="rename_template"><input type="hidden" name="id" value="<?=e($template['id'])?>"><input class="form-control form-control-sm" name="title" maxlength="180" value="<?=e($template['title'])?>" required aria-label="Template task"><button class="btn btn-sm btn-outline-secondary">Save</button></form><form method="post" class="mt-1"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="toggle_template"><input type="hidden" name="id" value="<?=e($template['id'])?>"><button class="btn btn-sm btn-link px-0"><?=((int)$template['active']===1?'Disable for future months':'Enable for future months')?></button></form></div><?php endforeach;?><form method="post" class="d-flex gap-2 mt-3"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="add_template"><input class="form-control" name="title" maxlength="180" placeholder="New recurring task" required aria-label="New recurring task"><button class="btn btn-primary text-nowrap">Add default</button></form></section><p class="small text-secondary text-center mt-4">Your checklist history is stored in your database. Each month is independent.</p></main></body></html>